import pandas as pd

path='/root/data.xlsx'
df=pd.read_excel(path, sheet_name='Data', header=8)
cols=['Turn number','Game number','Roll 1','Roll 2','Roll 3','Roll 4','Roll 5','Roll 6']
df=df[cols]
df=df.dropna(subset=['Turn number','Game number'])
for c in cols:
    df[c]=df[c].astype(int)

categories=['High and Often','Summation','Highs and Lows','Only two numbers','All the numbers','Ordered subset of four']

def scores_for_turn(rolls):
    rolls=list(rolls)
    counts={i:rolls.count(i) for i in set(rolls)}
    maxv=max(rolls); minv=min(rolls)
    scores={}
    scores['High and Often']=maxv*counts[maxv]
    scores['Summation']=sum(rolls)
    scores['Highs and Lows']=maxv*minv*(maxv-minv)
    if len(set(rolls))==2:
        scores['Only two numbers']=30
    if set(rolls)=={1,2,3,4,5,6}:
        scores['All the numbers']=40
    def has_ordered_subset_of_four(rolls):
        n=len(rolls)
        for i in range(n-3):
            seq=rolls[i:i+4]
            if all(seq[j+1]-seq[j]==1 for j in range(3)):
                return True
            if all(seq[j]-seq[j+1]==1 for j in range(3)):
                return True
        return False
    if has_ordered_subset_of_four(rolls):
        scores['Ordered subset of four']=50
    return scores

# compute game scores

game_scores={}

for game, group in df.groupby('Game number'):
    group=group.sort_values('Turn number')
    if len(group)!=2:
        continue
    turn_dicts=[]
    for _,row in group.iterrows():
        rolls=[row[f'Roll {i}'] for i in range(1,7)]
        turn_dicts.append(scores_for_turn(rolls))
    if len(turn_dicts)!=2:
        continue
    best=-1
    for c1,s1 in turn_dicts[0].items():
        for c2,s2 in turn_dicts[1].items():
            if c1!=c2:
                total=s1+s2
                if total>best:
                    best=total
    game_scores[game]=best

print('games with 2 turns', len(game_scores), 'min', min(game_scores), 'max', max(game_scores))
# check for missing games
missing=[g for g in range(1, max(game_scores)+1) if g not in game_scores]
print('missing count', len(missing))

player1_wins=player2_wins=ties=0
for game1 in range(1, max(game_scores), 2):
    game2=game1+1
    if game1 not in game_scores or game2 not in game_scores:
        continue
    s1=game_scores[game1]
    s2=game_scores[game2]
    if s1>s2:
        player1_wins+=1
    elif s2>s1:
        player2_wins+=1
    else:
        ties+=1

print('player1', player1_wins, 'player2', player2_wins, 'ties', ties)
print('diff', player1_wins-player2_wins)
